package com.phamquocviet.apigateway.filter;import org.springframework.beans.factory.annotation.Value;import org.springframework.cloud.gateway.filter.*;import org.springframework.core.Ordered;import org.springframework.http.*;import org.springframework.stereotype.Component;import org.springframework.web.server.*;import reactor.core.publisher.Mono;import java.nio.charset.StandardCharsets;
@Component public class ApiKeyFilter implements GlobalFilter,Ordered{private final String key;public ApiKeyFilter(@Value("${gateway.api-key}")String k){key=k;}public Mono<Void> filter(ServerWebExchange x,GatewayFilterChain c){if(!x.getRequest().getPath().value().startsWith("/api/public/courses"))return c.filter(x);if(key.equals(x.getRequest().getHeaders().getFirst("X-API-KEY")))return c.filter(x);x.getResponse().setStatusCode(HttpStatus.FORBIDDEN);x.getResponse().getHeaders().setContentType(MediaType.APPLICATION_JSON);return x.getResponse().writeWith(Mono.just(x.getResponse().bufferFactory().wrap("{\"status\":403,\"error\":\"Forbidden\",\"message\":\"API key không hợp lệ\"}".getBytes(StandardCharsets.UTF_8))));}public int getOrder(){return-9;}}
